namespace ghidra.test;

using docking;
using ghidra.framework.model;
using ghidra.framework.project.tool;
using ghidra.util;
using ghidra.util.exception;

public class TestTool : GhidraTool {
	public static string NAME = "Test Tool";

	public TestTool(Project project) : base(project, NAME)
    {
		winMgr.setWindowsOnTop(true);
	}

	/* @Override */
	protected DockingWindowManager createDockingWindowManager(bool isDockable, bool hasStatus,
			bool isModal) {
		return new DockingWindowManager(this, null, isModal, isDockable, hasStatus, null);
	}

	/* @Override */
	public void close() {
		if (isExecutingCommand()) {
			throw new AssertException("Attempted to close tool while background command running");
		}

		Runnable r = () => {
			dispose();
			if (getProject().getToolServices() != null) {
				getProject().getToolServices().closeTool(this);
			}
		};

		SystemUtilities.runSwingNow(r);
	}
}
